def st_read(
    file_name: _E[_t.Varchar] | str,
    /,
    *,
    open_options: _PyList | None = None,
    allowed_drivers: _PyList | None = None,
    sibling_files: _PyList | None = None,
    layer: str | None = None,
    max_batch_size: int | None = None,
    keep_wkb: bool | None = None,
) -> _TableFunction:
    """Read and import a variety of geospatial file formats using the GDAL library. The `ST_Read` table function is based on the [GDAL](https://gdal.org/index.html) translator library and enables reading spatial data from a variety of geospatial vector file formats as if they were DuckDB tables. > See [ST_Drivers](#st_drivers) for a list of supported file formats and drivers. Except for the `path` parameter, all parameters are optional. | Parameter | Type | Description | | --------- | -----| ----------- | | `path` | VARCHAR | The path to the file to read. Mandatory | | `sequential_layer_scan` | BOOLEAN | If set to true, the table function will scan through all layers sequentially and return the first layer that matches the given layer name. This is required for some drivers to work properly, e.g., the OSM driver. | | `spatial_filter` | WKB_BLOB | If set to a WKB blob, the table function will only return rows that intersect with the given WKB geometry. Some drivers may support efficient spatial filtering natively, in which case it will be pushed down. Otherwise the filtering is done by GDAL which may be much slower. | | `open_options` | VARCHAR[] | A list of key-value pairs that are passed to the GDAL driver to control the opening of the file. E.g., the GeoJSON driver supports a FLATTEN_NESTED_ATTRIBUTES=YES option to flatten nested attributes. | | `layer` | VARCHAR | The name of the layer to read from the file. If NULL, the first layer is returned. Can also be a layer index (starting at 0). | | `allowed_drivers` | VARCHAR[] | A list of GDAL driver names that are allowed to be used to open the file. If empty, all drivers are allowed. | | `sibling_files` | VARCHAR[] | A list of sibling files that are required to open the file. E.g., the ESRI Shapefile driver requires a .shx file to be present. Although most of the time these can be discovered automatically. | | `spatial_filter_box` | BOX_2D | If set to a BOX_2D, the table function will only return rows that intersect with the given bounding box. Similar to spatial_filter. | | `keep_wkb` | BOOLEAN | If set, the table function will return geometries in a wkb_geometry column with the type WKB_BLOB (which can be cast to BLOB) instead of GEOMETRY. This is useful if you want to use DuckDB with more exotic geometry subtypes that DuckDB spatial doesn't support representing in the GEOMETRY type yet. | Note that GDAL is single-threaded, so this table function will not be able to make full use of parallelism. By using `ST_Read`, the spatial extension also provides “replacement scans” for common geospatial file formats, allowing you to query files of these formats as if they were tables directly. ```sql SELECT * FROM './path/to/some/shapefile/dataset.shp'; ``` In practice this is just syntax-sugar for calling ST_Read, so there is no difference in performance. If you want to pass additional options, you should use the ST_Read table function directly. The following formats are currently recognized by their file extension: | Format | Extension | | ------ | --------- | | ESRI ShapeFile | .shp | | GeoPackage | .gpkg | | FlatGeoBuf | .fgb |

    Example: `-- Read a Shapefile SELECT * FROM ST_Read('some/file/path/filename.shp'); -- Read a GeoJSON file CREATE TABLE my_geojson_table AS SELECT * FROM ST_Read('some/file/path/filename.json');`

    SQL: `ST_Read`"""
    return _rt.table(
        "ST_Read",
        (file_name,),
        {
            "open_options": open_options,
            "allowed_drivers": allowed_drivers,
            "sibling_files": sibling_files,
            "layer": layer,
            "max_batch_size": max_batch_size,
            "keep_wkb": keep_wkb,
        },
        "spatial",
    )


